import math


def find_solution(a, b, n):
    if a == 0:
        return None
    if b == 0:
        return None
    if n % math.gcd(a, b) != 0:
        return None
    x = (n * b) // math.gcd(a, b)
    y = (n - a * x) // b
    return x, y


